    tx={t['id']:t for t in r['transactions']}
    if not isinstance(order,list) or len(order)!=len(tx) or any(not isinstance(x,str) for x in order) or set(order)!=set(tx): return False
    ranks={x:i for i,x in enumerate(order)}
    for a in tx.values():
