        elif tag == 'del':
            d.pop(op[1], None)
        elif tag == 'cas':
            key = op[1]; old = op[2]; new = op[3]; want = op[4]
            ok = (d.get(key) == old)
            if ok != want:
                return None
            if ok:
                if new is None:
                    d.pop(key, None)
                else:
                    d[key] = new
        elif tag == 'scan':
            low = op[1]; high = op[2]
            got = [[k, v] for k, v in sorted(d.items()) if low <= k < high]
            if got != op[3]:
                return None
        else:
            return None
    return d

def solve(request):
    txs = request['transactions']
    n = len(txs)
    initial = dict(request['initial'])
    final = request['final']
    if n == 0:
        return {'order': [] if initial == final else None}
    ids = [t['id'] for t in txs]
    starts = [t['start'] for t in txs]
    ends = [t['end'] for t in txs]
    ops = [t['ops'] for t in txs]
    # predecessor mask: j must come before i if ends[j] <= starts[i]
    pred = [0]*n
    for i in range(n):
        m = 0
        for j in range(n):
            if i != j and ends[j] <= starts[i]:
                m |= (1 << j)
        pred[i] = m
    full = (1 << n) - 1
    final_key = tuple(sorted(final.items()))

    def statetuple(d):
        return tuple(sorted(d.items()))

    memo_fail = set()

    def dfs(mask, state):
        if mask == full:
            return [] if state == final else None
        key = (mask, statetuple(state))
        if key in memo_fail:
            return None
        # candidate ordering: those with observations first? try simple
        for i in range(n):
