                return False
        elif tag == 'put':
            d[op[1]] = op[2]
        elif tag == 'del':
            d.pop(op[1], None)
        elif tag == 'cas':
            key = op[1]; old = op[2]; new = op[3]; want = op[4]
            ok = (d.get(key) == old)
            if ok != want:
                return False
            if ok:
