            got = [[k, v] for k, v in sorted(d.items()) if low <= k < high]
            if got != op[3]:
                return False
        else:
            return False
    return True


def solve(request):
    txs = request['transactions']
    n = len(txs)
    initial = dict(request['initial'])
    final = dict(request['final'])

    if n == 0:
        return {'order': [] if initial == final else None}

    ids = [t['id'] for t in txs]
    starts = [t['start'] for t in txs]
    ends = [t['end'] for t in txs]
    ops = [t['ops'] for t in txs]

    # exact write set of each transaction: key -> value (None == delete/absent)
    writes = []
    keys = set(initial) | set(final)
    for i in range(n):
        w = {}
        for op in ops[i]:
            tag = op[0]
            if tag == 'put':
                w[op[1]] = op[2]
            elif tag == 'del':
                w[op[1]] = None
            elif tag == 'cas':
                if op[4]:  # success required -> writes new value
                    w[op[1]] = op[3]
        writes.append(w)
        keys.update(w)

    # key -> list of transaction indices that write it
    writers = {k: [i for i in range(n) if k in writes[i]] for k in keys}

    # final value per key (None == absent)
    finalv = {k: final.get(k) for k in keys}

    # predecessor mask: j must precede i iff ends[j] <= starts[i]
    pred = [0] * n
    for i in range(n):
        m = 0
        for j in range(n):
            if i != j and ends[j] <= starts[i]:
                m |= (1 << j)
        pred[i] = m

    full = (1 << n) - 1

