    for k in keys:
        if not writers[k] and initial.get(k) != finalv[k]:
            return {'order': None}

    def statetuple(d):
        return tuple(sorted(d.items()))

    def feasible(mask, state):
        for k in keys:
            rem = [i for i in writers[k] if not (mask >> i) & 1]
            fv = finalv[k]
            if not rem:
                if state.get(k) != fv:
                    return False
            else:
                prods = [i for i in rem if writes[i][k] == fv]
                if not prods:
                    return False
        return True

    def can_place(mask, i):
        # unique remaining producer for some key cannot be placed while other writers remain
        for k, v in writes[i].items():
            if v != finalv[k]:
                continue
            # is i the only remaining producer of final value for k?
            others = False
            for j in writers[k]:
                if j != i and not (mask >> j) & 1 and writes[j][k] == finalv[k]:
                    others = True
                    break
            if not others:
